from azure.identity import DefaultAzureCredential
from azure.keyvault.keys.crypto import CryptographyClient, SignatureAlgorithm

def sign_or_verify_key(data, config=None, operation='sign'):
    config = config or {}
    with DefaultAzureCredential() as credential:
        key_id = config.get('key_id')
        if not key_id:
            raise ValueError("Key ID is required for signing or verification.")

        with CryptographyClient(key_id, credential=credential) as client:
            if operation == 'sign':
                # Hash the data before signing if the key expects a hash
                import hashlib
                digest = hashlib.sha256(data['payload']).digest()
                sign_response = client.sign(SignatureAlgorithm.rs256, digest)
                return {'signature': sign_response.signature, 'key_id': sign_response.key_id, 'algorithm': 'RS256'}
            elif operation == 'verify':
                import hashlib
                digest = hashlib.sha256(data['payload']).digest()
                verify_response = client.verify(SignatureAlgorithm.rs256, digest, data['signature'])
                return {'is_valid': verify_response.is_valid, 'key_id': key_id, 'algorithm': 'RS256'}
            else:
                raise ValueError("Operation must be 'sign' or 'verify'.")

from azure.identity import DefaultAzureCredential
from azure.keyvault.keys import KeyClient
from azure.keyvault.keys.crypto import CryptographyClient
import os

def get_key_client(vault_url):
    credential = DefaultAzureCredential()
    return KeyClient(vault_url=vault_url, credential=credential)

def get_cryptography_client(key_id):
    credential = DefaultAzureCredential()
    return CryptographyClient(key_id=key_id, credential=credential)

def get_key_vault_url():
    # In a real application, this would be loaded from environment variables or a configuration file
    return os.environ.get("AZURE_KEY_VAULT_URL", "https://<your-key-vault-name>.vault.azure.net")

def get_key_id():
    # In a real application, this would be loaded from environment variables or a configuration file
    return os.environ.get("AZURE_KEY_ID", "https://<your-key-vault-name>.vault.azure.net/keys/<your-key-name>/<your-key-version>")

import json

def normalize_payload(data):
    # Basic normalization for consistency
    if isinstance(data, dict):
        return json.dumps(data, sort_keys=True).encode('utf-8')
    elif isinstance(data, str):
        return data.encode('utf-8')
    elif isinstance(data, bytes):
        return data
    else:
        raise TypeError("Unsupported payload type for normalization.")

def denormalize_response(data):
    # Basic denormalization for consistency
    if isinstance(data, bytes):
        try:
            return json.loads(data.decode('utf-8'))
        except json.JSONDecodeError:
            return data.decode('utf-8')
    return data

# Example request/response structures (can be expanded as needed)
class EncryptionRequest:
    def __init__(self, plaintext: bytes, key_id: str = None):
        self.plaintext = plaintext
        self.key_id = key_id

class EncryptionResponse:
    def __init__(self, ciphertext: bytes, iv: bytes, tag: bytes, key_id: str, algorithm: str):
        self.ciphertext = ciphertext
        self.iv = iv
        self.tag = tag
        self.key_id = key_id
        self.algorithm = algorithm

class DecryptionRequest:
